Use the active sheet as the answer sheet and read the three data rows from rows 1-3.  
For each column B-E, find the maximum value among the three rows and count how many rows tie for that maximum.  
Write 6, 3, 2, or 0 to the matching answer rows 5-7 according to the tie count.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals[ws.title] if ws.title in vals.sheetnames else vals.active

data_rows = [1, 2, 3]
answer_rows = [5, 6, 7]
cols = list(range(2, 6))  # B, C, D, E

label_to_data_row = {}
for r in data_rows:
    label = vws.cell(row=r, column=1).value
    if label is not None:
        label_to_data_row[str(label).strip()] = r

def data_row_for_answer_row(answer_row):
    label = vws.cell(row=answer_row, column=1).value
    if label is not None:
        key = str(label).strip()
        if key in label_to_data_row:
            return label_to_data_row[key]
    return answer_row - 4

def to_number(value):
    if isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return float(value)
    if value is None:
        return None
    try:
        return float(str(value).strip())
    except Exception:
        return None

for col in cols:
    column_values = []
    for r in data_rows:
        v = to_number(vws.cell(row=r, column=col).value)
        if v is not None:
            column_values.append((r, v))

    if not column_values:
        scores = {r: 0 for r in data_rows}
    else:
        max_value = max(v for _, v in column_values)
        tied_rows = [r for r, v in column_values if abs(v - max_value) <= 1e-9]
        tied_count = len(tied_rows)

        if tied_count == 1:
            points = 6
        elif tied_count == 2:
            points = 3
        elif tied_count >= 3:
            points = 2
        else:
            points = 0

        scores = {r: (points if r in tied_rows else 0) for r in data_rows}

    for answer_row in answer_rows:
        data_row = data_row_for_answer_row(answer_row)
        ws.cell(row=answer_row, column=col).value = int(scores.get(data_row, 0))

print("active sheet:", ws.title)
print("data rows:", len(data_rows), "answer rows:", len(answer_rows))
for r in answer_rows:
    print(r, [ws.cell(row=r, column=c).value for c in cols])

wb.save(OUT)
